drop policy if exists "Admins can view all case updates" on public.case_updates; create policy "Authorised staff can view case updates" on public.case_updates for select to authenticated using (public.is_super_admin((select auth.uid())) or (public.is_campus_admin((select auth.uid())) and exists (select 1 from public.incidents i where i.id = incident_id and i.campus = public.get_user_campus((select auth.uid())))));